"""Command line entry point."""

from __future__ import annotations

import argparse
import os
import sys
from typing import Sequence

# Exit codes
EXIT_OK = 0  # no mismatches
EXIT_MISMATCH = 1  # mismatches found
EXIT_ERROR = 2  # could not run

KEY_VARS = ("NEATLOGS_API_KEY", "TRUEUP_MODEL_KEY")
NOT_BUILT = ("audit", "sweep", "fix", "upstream", "verify", "report")


def doctor() -> int:
    ok = sys.version_info >= (3, 12)
    v = sys.version_info
    print(f"python: {v.major}.{v.minor}.{v.micro} ({'ok' if ok else 'need 3.12+'})")
    for name in KEY_VARS:
        # Only report presence. Never print the value.
        state = "set" if os.environ.get(name) else "not set"
        print(f"{name}: {state}")
    return EXIT_OK if ok else EXIT_ERROR


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="trueup",
        description="Find where AI agent traces disagree with what really happened.",
    )
    sub = parser.add_subparsers(dest="command", required=True)
    for name in NOT_BUILT:
        sub.add_parser(name, help="not built yet")
    sub.add_parser("doctor", help="check the local setup")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "doctor":
        return doctor()
    print(f"trueup {args.command}: not built yet", file=sys.stderr)
    return EXIT_ERROR


if __name__ == "__main__":
    sys.exit(main())
"""Pure core: data model and logic with no I/O."""

from trueup.core.model import Finding, Mismatch, Observation, Run, Severity

__all__ = ["Finding", "Mismatch", "Observation", "Run", "Severity"]
"""Data model. Plain dataclasses with to_dict/from_dict. No I/O here."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class Severity(Enum):
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"

    @property
    def rank(self) -> int:
        # Higher rank means more severe.
        return {"high": 3, "medium": 2, "low": 1}[self.value]

    def __lt__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank < other.rank

    def __le__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank <= other.rank

    def __gt__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank > other.rank

    def __ge__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank >= other.rank


@dataclass(frozen=True)
class Observation:
    """What really happened (truth) next to what the trace recorded (trace)."""

    truth: dict[str, Any]
    trace: dict[str, Any]

    def to_dict(self) -> dict[str, Any]:
        return {"truth": dict(self.truth), "trace": dict(self.trace)}

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Observation:
        return cls(truth=dict(d["truth"]), trace=dict(d["trace"]))


@dataclass(frozen=True)
class Mismatch:
    """One field where truth and trace disagree."""

    field: str
    truth: Any
    trace: Any
    severity: Severity

    def to_dict(self) -> dict[str, Any]:
        return {
            "field": self.field,
            "truth": self.truth,
            "trace": self.trace,
            "severity": self.severity.value,
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Mismatch:
        return cls(
            field=d["field"],
            truth=d["truth"],
            trace=d["trace"],
            severity=Severity(d["severity"]),
        )


@dataclass(frozen=True)
class Run:
    """One scenario run against the fake provider."""

    id: str
    scenario: str
    library: str
    observation: Observation
    mismatches: tuple[Mismatch, ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "scenario": self.scenario,
            "library": self.library,
            "observation": self.observation.to_dict(),
            "mismatches": [m.to_dict() for m in self.mismatches],
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Run:
        return cls(
            id=d["id"],
            scenario=d["scenario"],
            library=d["library"],
            observation=Observation.from_dict(d["observation"]),
            mismatches=tuple(Mismatch.from_dict(m) for m in d.get("mismatches", [])),
        )


@dataclass(frozen=True)
class Finding:
    """A confirmed, deduplicated problem in a tracing library."""

    id: str
    title: str
    library: str
    severity: Severity
    run_ids: tuple[str, ...] = ()
    cause: str | None = None
    details: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "title": self.title,
            "library": self.library,
            "severity": self.severity.value,
            "run_ids": list(self.run_ids),
            "cause": self.cause,
            "details": dict(self.details),
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Finding:
        return cls(
            id=d["id"],
            title=d["title"],
            library=d["library"],
            severity=Severity(d["severity"]),
            run_ids=tuple(d.get("run_ids", [])),
            cause=d.get("cause"),
            details=dict(d.get("details", {})),
        )
"""Trueup: compare AI agent traces with what really happened."""

__version__ = "0.0.1"
import pytest

from trueup.cli import EXIT_ERROR, EXIT_OK, NOT_BUILT, main

SECRET_A = "nl-secret-value-123"
SECRET_B = "model-secret-value-456"


def test_doctor_with_keys_set_never_prints_values(monkeypatch, capsys):
    monkeypatch.setenv("NEATLOGS_API_KEY", SECRET_A)
    monkeypatch.setenv("TRUEUP_MODEL_KEY", SECRET_B)
    assert main(["doctor"]) == EXIT_OK
    out, err = capsys.readouterr()
    assert "NEATLOGS_API_KEY: set" in out
    assert "TRUEUP_MODEL_KEY: set" in out
    assert "python: 3." in out
    for secret in (SECRET_A, SECRET_B):
        assert secret not in out
        assert secret not in err


def test_doctor_with_keys_missing(monkeypatch, capsys):
    monkeypatch.delenv("NEATLOGS_API_KEY", raising=False)
    monkeypatch.delenv("TRUEUP_MODEL_KEY", raising=False)
    assert main(["doctor"]) == EXIT_OK
    out = capsys.readouterr().out
    assert "NEATLOGS_API_KEY: not set" in out
    assert "TRUEUP_MODEL_KEY: not set" in out


@pytest.mark.parametrize("command", NOT_BUILT)
def test_unbuilt_commands_exit_2(command, capsys):
    assert main([command]) == EXIT_ERROR
    assert "not built yet" in capsys.readouterr().err
import json

from trueup.core import Finding, Mismatch, Observation, Run, Severity


def make_run() -> Run:
    obs = Observation(
        truth={"status": "error", "cost_usd": 0.01},
        trace={"status": "ok", "cost_usd": 0.02},
    )
    return Run(
        id="r1",
        scenario="crash-mid-stream",
        library="openinference",
        observation=obs,
        mismatches=(
            Mismatch("status", "error", "ok", Severity.HIGH),
            Mismatch("cost_usd", 0.01, 0.02, Severity.MEDIUM),
        ),
    )


def test_observation_round_trip():
    obs = Observation(truth={"a": 1}, trace={"a": 2})
    assert Observation.from_dict(obs.to_dict()) == obs


def test_mismatch_round_trip():
    m = Mismatch("refusal", True, False, Severity.LOW)
    assert Mismatch.from_dict(m.to_dict()) == m


def test_run_round_trip_through_json():
    run = make_run()
    assert Run.from_dict(json.loads(json.dumps(run.to_dict()))) == run


def test_finding_round_trip_through_json():
    f = Finding(
        id="f1",
        title="Stream crash recorded as ok",
        library="openinference",
        severity=Severity.HIGH,
        run_ids=("r1", "r2"),
        cause="exception swallowed in stream wrapper",
        details={"file": "wrapper.py"},
    )
    assert Finding.from_dict(json.loads(json.dumps(f.to_dict()))) == f


def test_finding_defaults_round_trip():
    f = Finding(id="f2", title="t", library="l", severity=Severity.LOW)
    assert Finding.from_dict(f.to_dict()) == f


def test_severity_ordering():
    assert Severity.LOW < Severity.MEDIUM < Severity.HIGH
    assert Severity.HIGH >= Severity.HIGH
    assert sorted([Severity.MEDIUM, Severity.HIGH, Severity.LOW]) == [
        Severity.LOW,
        Severity.MEDIUM,
        Severity.HIGH,
    ]
    assert max(Severity) is Severity.HIGH
# Fake OpenAI + Anthropic server. Scenario is chosen by the request's model name.
import json, threading, socket
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
def oa_chunk(delta, fr=None, usage=None, idx=0, choices=True):
    d = {"id":"c1","object":"chat.completion.chunk","created":0,"model":"gpt-x","choices":[{"index":idx,"delta":delta,"finish_reason":fr}] if choices else []}
    if usage: d["usage"] = usage
    return f"data: {json.dumps(d)}\n\n".encode()
def sse(ev, d): return f"event: {ev}\ndata: {json.dumps(d)}\n\n".encode()
U = {"prompt_tokens":11,"completion_tokens":7,"total_tokens":18}
def oa_chat(sc, req):
    tc2 = [{"id":"call_a","type":"function","function":{"name":"get_weather","arguments":"{\"city\":\"Lagos\"}"}},
           {"id":"call_b","type":"function","function":{"name":"get_time","arguments":"{\"tz\":\"WAT\"}"}}]
    if not req.get("stream"):
        if sc == "err500": return 500, "application/json", json.dumps({"error":{"message":"boom","type":"server_error"}}).encode()
        if sc == "n2":
            ch = [{"index":0,"message":{"role":"assistant","content":"one"},"finish_reason":"stop"},{"index":1,"message":{"role":"assistant","content":"two"},"finish_reason":"stop"}]
        elif sc == "tools":
            ch = [{"index":0,"message":{"role":"assistant","content":None,"tool_calls":tc2},"finish_reason":"tool_calls"}]
        elif sc == "refusal":
            ch = [{"index":0,"message":{"role":"assistant","content":None,"refusal":"I can't help with that."},"finish_reason":"stop"}]
        else:
            ch = [{"index":0,"message":{"role":"assistant","content":"hello"},"finish_reason":"stop"}]
        return 200, "application/json", json.dumps({"id":"c1","object":"chat.completion","created":0,"model":"gpt-x","choices":ch,"usage":U}).encode()
    p = [oa_chunk({"role":"assistant","content":""})]
    if sc in ("s_tools",):
        # parallel tool calls, args split across chunks, interleaved
        p += [oa_chunk({"tool_calls":[{"index":0,"id":"call_a","type":"function","function":{"name":"get_weather","arguments":""}}]}),
              oa_chunk({"tool_calls":[{"index":1,"id":"call_b","type":"function","function":{"name":"get_time","arguments":""}}]}),
              oa_chunk({"tool_calls":[{"index":0,"function":{"arguments":"{\"city\":"}}]}),
              oa_chunk({"tool_calls":[{"index":1,"function":{"arguments":"{\"tz\":\"WAT\"}"}}]}),
              oa_chunk({"tool_calls":[{"index":0,"function":{"arguments":"\"Lagos\"}"}}]}),
              oa_chunk({}, "tool_calls")]
    else:
        p += [oa_chunk({"content":"hel"})]
        if sc == "s_errevent":
            p.append(f"data: {json.dumps({'error':{'message':'server overloaded','type':'server_error'}})}\n\n".encode()); return 200, "text/event-stream", b"".join(p)
        if sc == "s_cut":
            return 200, "text/event-stream", ("CUT", b"".join(p))
        p += [oa_chunk({"content":"lo"}), oa_chunk({}, "stop")]
    if (req.get("stream_options") or {}).get("include_usage"):
        p.append(oa_chunk(None, usage=U, choices=False))
    p.append(b"data: [DONE]\n\n")
    return 200, "text/event-stream", b"".join(p)
def an_msg(sc, req):
    if sc == "a_err529": return 529, "application/json", json.dumps({"type":"error","error":{"type":"overloaded_error","message":"Overloaded"}}).encode()
    if not req.get("stream"):
        return 200, "application/json", json.dumps({"id":"m1","type":"message","role":"assistant","model":"claude-x","stop_reason":"end_turn","stop_sequence":None,"content":[{"type":"text","text":"hello"}],"usage":{"input_tokens":5,"output_tokens":3}}).encode()
    p = [sse("message_start", {"type":"message_start","message":{"id":"m1","type":"message","role":"assistant","model":"claude-x","content":[],"stop_reason":None,"usage":{"input_tokens":5,"output_tokens":1}}})]
    i = 0
    if sc in ("a_think","a_tools"):
        p += [sse("content_block_start", {"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":""}}),
              sse("content_block_delta", {"type":"content_block_delta","index":0,"delta":{"type":"thinking_delta","thinking":"Need weather."}}),
              sse("content_block_delta", {"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":"sig"}}),
              sse("content_block_stop", {"type":"content_block_stop","index":0})]; i = 1
    p += [sse("content_block_start", {"type":"content_block_start","index":i,"content_block":{"type":"text","text":""}}),
          sse("content_block_delta", {"type":"content_block_delta","index":i,"delta":{"type":"text_delta","text":"hel"}})]
    if sc == "a_errevent":
        p.append(sse("error", {"type":"error","error":{"type":"overloaded_error","message":"Overloaded"}})); return 200, "text/event-stream", b"".join(p)
    if sc == "a_cut": return 200, "text/event-stream", ("CUT", b"".join(p))
    p += [sse("content_block_delta", {"type":"content_block_delta","index":i,"delta":{"type":"text_delta","text":"lo"}}),
          sse("content_block_stop", {"type":"content_block_stop","index":i})]
    sr = "end_turn"
    if sc == "a_tools":
        p += [sse("content_block_start", {"type":"content_block_start","index":i+1,"content_block":{"type":"tool_use","id":"toolu_1","name":"get_weather","input":{}}}),
              sse("content_block_delta", {"type":"content_block_delta","index":i+1,"delta":{"type":"input_json_delta","partial_json":"{\"city\": "}}),
              sse("content_block_delta", {"type":"content_block_delta","index":i+1,"delta":{"type":"input_json_delta","partial_json":"\"Lagos\"}"}}),
              sse("content_block_stop", {"type":"content_block_stop","index":i+1})]; sr = "tool_use"
    p += [sse("message_delta", {"type":"message_delta","delta":{"stop_reason":sr,"stop_sequence":None},"usage":{"output_tokens":3}}), sse("message_stop", {"type":"message_stop"})]
    return 200, "text/event-stream", b"".join(p)
def responses(sc, req):
    out = [{"type":"reasoning","id":"rs_1","summary":[{"type":"summary_text","text":"Think about weather."}]},
           {"type":"function_call","id":"fc_1","call_id":"call_a","name":"get_weather","arguments":"{\"city\":\"Lagos\"}","status":"completed"},
           {"type":"message","id":"msg_1","role":"assistant","status":"completed","content":[{"type":"output_text","text":"hello","annotations":[]}]}]
    body = {"id":"resp_1","object":"response","created_at":0,"status":"completed","model":"gpt-x","output":out,"parallel_tool_calls":True,"tool_choice":"auto","tools":[],
            "usage":{"input_tokens":11,"output_tokens":7,"total_tokens":18,"input_tokens_details":{"cached_tokens":0},"output_tokens_details":{"reasoning_tokens":4}}}
    if sc == "r_incomplete":
        body["id"] = "resp_3"; body["status"] = "incomplete"; body["incomplete_details"] = {"reason":"max_output_tokens"}; body["output"] = [out[2]]; body["output"][0]["status"] = "incomplete"; body["output"][0]["content"][0]["text"] = "The answer is cut"
    if sc == "r_fail":
        body["id"] = "resp_2"
        body["status"] = "failed"; body["error"] = {"code":"server_error","message":"failed"}; body["output"] = []
    return 200, "application/json", json.dumps(body).encode()
class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    def log_message(self, *a): pass
    def do_POST(self):
        req = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        sc = req.get("model","")
        fn = an_msg if self.path.endswith("/messages") else responses if self.path.endswith("/responses") else oa_chat
        code, ct, body = fn(sc, req)
        if isinstance(body, tuple):  # write part, then drop the connection
            self.send_response(code); self.send_header("Content-Type", ct); self.send_header("Content-Length", str(len(body[1]) + 500)); self.end_headers()
            self.wfile.write(body[1]); self.wfile.flush(); self.connection.shutdown(socket.SHUT_RDWR); self.close_connection = True; return
        self.send_response(code); self.send_header("Content-Type", ct); self.send_header("Content-Length", str(len(body))); self.end_headers(); self.wfile.write(body)
def start():
    s = ThreadingHTTPServer(("127.0.0.1", 0), H); threading.Thread(target=s.serve_forever, daemon=True).start(); return s.server_port
