import sys, os, json, gc, asyncio, time, logging
logging.disable(logging.CRITICAL)
sys.path.insert(0, os.path.dirname(__file__)); import fake
LIB = sys.argv[1]; ONLY = sys.argv[2:] 
port = fake.start(); base = f"http://127.0.0.1:{port}"
os.environ["OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT"] = "true"; os.environ["TRACELOOP_TRACE_CONTENT"] = "true"
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import SimpleSpanProcessor
from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter
exp = InMemorySpanExporter()
if LIB == "neatlogs":
    import neatlogs; neatlogs.init(api_key="nl-dummy", instrumentations=["openai","anthropic"], endpoint="http://127.0.0.1:9")
    sys.modules["neatlogs.init"]._tracer_provider.add_span_processor(SimpleSpanProcessor(exp))
else:
    tp = TracerProvider(); tp.add_span_processor(SimpleSpanProcessor(exp))
    if LIB == "ollm":
        from opentelemetry.instrumentation.openai import OpenAIInstrumentor; from opentelemetry.instrumentation.anthropic import AnthropicInstrumentor
    else:
        from openinference.instrumentation.openai import OpenAIInstrumentor; from openinference.instrumentation.anthropic import AnthropicInstrumentor
    OpenAIInstrumentor().instrument(tracer_provider=tp); AnthropicInstrumentor().instrument(tracer_provider=tp)
import openai, anthropic
oc = openai.OpenAI(api_key="x", base_url=base+"/v1", max_retries=0); aoc = openai.AsyncOpenAI(api_key="x", base_url=base+"/v1", max_retries=0)
ac = anthropic.Anthropic(api_key="x", base_url=base, max_retries=0); aac = anthropic.AsyncAnthropic(api_key="x", base_url=base, max_retries=0)
M = [{"role":"user","content":"hi"}]
TOOLS = [{"type":"function","function":{"name":"get_weather","parameters":{"type":"object","properties":{"city":{"type":"string"}}}}}]
ATOOLS = [{"name":"get_weather","input_schema":{"type":"object","properties":{"city":{"type":"string"}}}}]
def oa_stream(sc, **kw):
    t = {"text":"", "tools":{}, "usage":None}
    for ch in oc.chat.completions.create(model=sc, messages=M, stream=True, **kw):
        if ch.usage: t["usage"] = ch.usage.total_tokens
        for c in ch.choices:
            t["text"] += c.delta.content or ""
            for tc in c.delta.tool_calls or []:
                d = t["tools"].setdefault(tc.index, {"name":"", "args":""})
                if tc.function.name: d["name"] = tc.function.name
                d["args"] += tc.function.arguments or ""
    return t
def oa_break(sc):
    s = oc.chat.completions.create(model=sc, messages=M, stream=True)
    for ch in s: break
    s.close(); return {"broke_after_first_chunk": True}
def oa_break_noclose(sc):
    s = oc.chat.completions.create(model=sc, messages=M, stream=True)
    for ch in s: break
    del s; gc.collect(); return {"broke_without_close": True}
async def oa_astream(sc):
    t = ""
    async for ch in await aoc.chat.completions.create(model=sc, messages=M, stream=True, stream_options={"include_usage":True}):
        for c in ch.choices: t += c.delta.content or ""
    return {"text": t}
def an_stream(sc, helper="text_stream", **kw):
    t = {"text":""}
    with ac.messages.stream(model=sc, max_tokens=50, messages=M, **kw) as s:
        if helper == "text_stream":
            for x in s.text_stream: t["text"] += x
        fm = s.get_final_message()
        t["blocks"] = [b.type for b in fm.content]; t["usage"] = (fm.usage.input_tokens, fm.usage.output_tokens)
        t["tool_input"] = [b.input for b in fm.content if b.type == "tool_use"]
    return t
def an_create_stream(sc):
    t = ""
    for ev in ac.messages.create(model=sc, max_tokens=50, messages=M, stream=True):
        if ev.type == "content_block_delta" and ev.delta.type == "text_delta": t += ev.delta.text
    return {"text": t}
def an_break(sc):
    s = ac.messages.create(model=sc, max_tokens=50, messages=M, stream=True)
    for ev in s: break
    s.close(); return {"broke_after_first_event": True}
async def an_acreate(sc):
    r = await aac.messages.create(model=sc, max_tokens=50, messages=M); return {"text": r.content[0].text}
def resp(sc):
    r = oc.responses.create(model=sc, input="hi")
    return {"status": r.status, "out_types": [o.type for o in r.output], "text": r.output_text, "reasoning_tokens": r.usage.output_tokens_details.reasoning_tokens if r.usage else None}
SC = {
 "oa_plain":      lambda: (lambda r: {"text": r.choices[0].message.content, "tokens": r.usage.total_tokens})(oc.chat.completions.create(model="plain", messages=M)),
 "oa_tools":      lambda: (lambda r: {"tools": [(t.function.name, t.function.arguments) for t in r.choices[0].message.tool_calls]})(oc.chat.completions.create(model="tools", messages=M, tools=TOOLS)),
 "oa_n2":         lambda: (lambda r: {"choices": [c.message.content for c in r.choices]})(oc.chat.completions.create(model="n2", messages=M, n=2)),
 "oa_refusal":    lambda: (lambda r: {"refusal": r.choices[0].message.refusal})(oc.chat.completions.create(model="refusal", messages=M)),
 "oa_err500":     lambda: oc.chat.completions.create(model="err500", messages=M),
 "oa_stream":     lambda: oa_stream("s_plain", stream_options={"include_usage":True}),
 "oa_s_tools":    lambda: oa_stream("s_tools", tools=TOOLS),
 "oa_s_errevent": lambda: oa_stream("s_errevent"),
 "oa_s_cut":      lambda: oa_stream("s_cut"),
 "oa_s_break":    lambda: oa_break("s_plain"),
 "oa_s_break_gc": lambda: oa_break_noclose("s_plain"),
 "oa_astream":    lambda: asyncio.run(oa_astream("s_plain")),
 "oa_raw":        lambda: (lambda r: {"text": r.parse().choices[0].message.content})(oc.chat.completions.with_raw_response.create(model="plain", messages=M)),
 "resp_full":     lambda: resp("r_full"),
 "resp_failed":   lambda: resp("r_fail"),
 "resp_incomplete": lambda: resp("r_incomplete"),
 "an_stream_helper": lambda: an_stream("a_plain"),
 "an_stream_think":  lambda: an_stream("a_think"),
 "an_stream_tools":  lambda: an_stream("a_tools", tools=ATOOLS),
 "an_create_stream": lambda: an_create_stream("a_plain"),
 "an_create_think":  lambda: an_create_stream("a_think"),
 "an_errevent":      lambda: an_create_stream("a_errevent"),
 "an_cut":           lambda: an_create_stream("a_cut"),
